// Complete, verbatim Vendora clauses shared by AI, validation and document generation.
// Initial migration extracts existing wording; it does not make legal policy changes.
(function(root,factory){var api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.AgreementClauses=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
function prose(items){return Array.isArray(items)?items.map(function(x){return typeof x==='string'?x:String(x&&x.t||'');}).join(''):String(items==null?'':items);}
var all={
"ra":[
 {id:"ra.s2.p1",section:"2",label:"§2 Interpretation / 1",when:function(data){return true;},items:function(data){return "This Agreement consists of a main agreement body and three (3) appendices. In the event of any inconsistency, the following order of precedence applies: (1) main agreement body; (2) Appendix 1; (3) Appendix 2; (4) Appendix 3; (5) any order placed under the Agreement.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s3.appointment",section:"3",label:"Appointment (§3)",when:function(data){return true;},items:function(data){return "The Supplier hereby grants to the Reseller a "+data.excl+" right to market and sell the Products within the Territory during the term of this Agreement. The Supplier has the right to amend its offered product range and/or product specifications at any time and at its sole discretion. This Agreement does not restrict the Supplier from appointing other resellers within the Territory or from selling the Products directly. Within the EU/EEA, passive sales (unsolicited orders) cannot be restricted regardless of territory.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.no_subreselling",section:"3",label:"No sub-reselling (§3)",when:function(data){return true;},items:function(data){return "The Reseller shall not appoint sub-resellers, sub-distributors, or sub-agents for the Products, nor grant any third party the right to sell or distribute the Products, without the prior written consent of the Supplier. Any such arrangement made without consent shall be null and void and shall constitute a material breach.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s3.p1",section:"3",label:"§3 Appointment and Territory / 1",when:function(data){return true;},items:function(data){return "Outside the Territory, the Reseller shall refrain from actively seeking customers or establishing distribution for the Products.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.marketplaces",section:"3",label:"Third-party marketplaces (§3)",when:function(data){return true;},items:function(data){return "Third-party online marketplaces. The Reseller shall not list, advertise, or sell the Products on any third-party online marketplace (including but not limited to Amazon, eBay, Bol, Cdiscount, Allegro, or similar platforms) without the Supplier’s prior written authorisation, which the Supplier may grant, withhold, condition, or revoke at its sole discretion. Any authorisation granted applies only to the specific marketplace, account, and territory identified, and may be subject to conditions on content and brand presentation. The Supplier may withdraw authorisation on written notice where marketplace activity conflicts with the Supplier’s or the brand owner’s own sales channels or brand strategy, and the Reseller shall cease the relevant listings within five (5) business days of such notice. Selling the Products on any marketplace without valid authorisation shall constitute a material breach.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s4.orders",section:"4",label:"Orders (§4)",when:function(data){return true;},items:function(data){return "Orders shall be placed through the Supplier\u2019s designated ordering channel and are subject to acceptance by the Supplier. The Supplier shall confirm or reject each order within two (2) business days of receipt; silence beyond this period constitutes acceptance.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s4.prices",section:"4",label:"Prices (§4)",when:function(data){return true;},items:function(data){return "Prices are as stated in the Supplier\u2019s current price list or web portal, excluding any applicable value added tax or sales tax. It is the Reseller\u2019s responsibility to ensure it uses the Supplier\u2019s current prices at all times. Current prices are made available (i) on the Supplier\u2019s website, and (ii) via a downloadable price file (XML or CSV) which the Supplier makes available for continuous retrieval. The Reseller shall not rely on any previously downloaded, cached, or historical price data. Shipping costs shall be governed by the shipping terms in Appendix 1 and Appendix 3. The Supplier reserves the right to amend Prices at any time; price changes apply to orders placed after the date the amended price list is published and shall not apply retroactively to orders already confirmed.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s4.payment",section:"4",label:"Payment (§4)",when:function(data){return true;},items:function(data){return "The Reseller shall pay for all ordered Products by bank transfer in "+data.curr+", within "+data.pay+" days from the invoice date. In the event of late payment, the Supplier is entitled to charge statutory interest, reminder fees, and collection costs. The Supplier also has the right to withhold further deliveries until full payment has been received.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s4.credit",section:"4",label:"Credit limit (§4)",when:function(data){return true;},items:function(data){return "The Supplier shall determine, at its sole discretion, whether to extend credit to the Reseller and the credit limit applicable (\u201cCredit Limit\u201d). The Credit Limit shall be communicated to the Reseller in writing and may be adjusted at any time upon no less than seven (7) days\u2019 written notice, except where the Supplier has reasonable grounds to suspect the Reseller\u2019s insolvency, in which case the Supplier may reduce or withdraw the Credit Limit with immediate effect. Credit Limit: "+(data.credit||"as agreed in writing")+".";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s4.title",section:"4",label:"Title retention (§4)",when:function(data){return true;},items:function(data){return "Title to all delivered Products shall remain vested in the Supplier until full payment of the purchase price has been received. In the event of the Reseller\u2019s insolvency, the Supplier has the right to reclaim unpaid Products without delay.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s5.p1",section:"5",label:"§5 Reseller’s Sales and Brand Compliance / 1",when:function(data){return true;},items:function(data){return "The Reseller is recommended, but not obligated, to adhere to the Suggested Retail Price (SRP) provided by the Supplier. The Reseller is free to set its own retail prices, provided that such practices comply with all applicable competition and antitrust laws.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s5.p2",section:"5",label:"§5 Reseller’s Sales and Brand Compliance / 2",when:function(data){return true;},items:function(data){return "The Reseller shall market and sell the Products in a professional manner consistent with the Supplier\u2019s brand guidelines. The Reseller shall not modify the Products, their packaging, or any labelling without the prior written consent of the Supplier.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s5.warranty",section:"5",label:"Warranty representations (§5)",when:function(data){return true;},items:function(data){return "The Reseller shall not misrepresent the scope, duration, or terms of the Supplier\u2019s standard warranty to end customers. The Reseller is free to offer end customers a commercial guarantee that exceeds the Supplier\u2019s standard warranty; any such additional guarantee is the Reseller\u2019s own commercial commitment and shall be fulfilled entirely at the Reseller\u2019s cost.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s5.p3",section:"5",label:"§5 Reseller’s Sales and Brand Compliance / 3",when:function(data){return true;},items:function(data){return [{t:"Marketing material approval. ",b:true},"Where marketing materials use the Supplier\u2019s trademarks, logos, or product claims, the Reseller shall submit such materials to the Supplier for approval prior to publication. The Supplier shall approve or provide comments within five (5) business days. If the Supplier does not respond within this period, the material shall be deemed approved for use in the Territory."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.s6.compliance",section:"6",label:"Compliance (§6)",when:function(data){return true;},items:function(data){return "Each Party shall comply with all applicable laws, regulations, business ethics, and industry standards, including: anti-bribery and anti-corruption laws; competition and antitrust laws; consumer protection and product safety laws; customs and export control laws; and sustainability and labour laws.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s6.p1",section:"6",label:"§6 Compliance with Laws / 1",when:function(data){return true;},items:function(data){return [{t:"Anti-grey market and anti-counterfeiting. ",b:true},"The Reseller shall not knowingly purchase, sell, or distribute Products sourced outside the Supplier\u2019s authorised supply chain. If the Reseller encounters or reasonably suspects the presence of grey market or counterfeit products in the Territory, the Reseller shall promptly notify the Supplier in writing and shall cooperate with the Supplier in any investigation or enforcement action at the Supplier\u2019s cost."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.s7.reporting",section:"7",label:"Reporting (§7)",when:function(data){return true;},items:function(data){return "The Reseller shall provide the Supplier with sell-through reports on a monthly basis, no later than ten (10) calendar days after the end of each calendar month. Each Sell-Through Report shall include: (i) units sold per Product SKU during the month; (ii) current closing inventory per SKU; and (iii) any significant developments in market conditions relevant to the Products.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s7.p1",section:"7",label:"§7 Reporting / 1",when:function(data){return (!!data.mdfb || !!data.mdft);},items:function(data){return [{t:"MDF eligibility linked to reporting. ",b:true},"Receipt of accurate and timely Sell-Through Reports is a condition for the Reseller\u2019s eligibility for Market Development Funds (MDF) in the following period. If the Reseller fails to submit a Sell-Through Report within the period specified, the Supplier may withhold MDF payments for the relevant period until the report has been received and verified."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.s8.confidentiality",section:"8",label:"Confidentiality (§8)",when:function(data){return true;},items:function(data){return "During the term of this Agreement, and for a period of three (3) years thereafter, the receiving Party undertakes not to disclose, without the disclosing Party\u2019s prior written consent, any Confidential Information regarding the disclosing Party\u2019s business, nor to use such information for any purpose other than the performance of its obligations under this Agreement.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s8.p1",section:"8",label:"§8 Confidentiality / 1",when:function(data){return true;},items:function(data){return "This confidentiality undertaking shall not apply to information that the receiving Party can prove it learned of in a manner other than through this Agreement, or which is or becomes public knowledge other than through a breach of this Agreement. Nor does this undertaking apply where the receiving Party is required to disclose information in accordance with any law, enactment, stock market regulation, or decision by a governmental authority or court.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s9.p1",section:"9",label:"§9 GDPR and Data Protection / 1",when:function(data){return true;},items:function(data){return "Both Parties agree to comply with the General Data Protection Regulation (GDPR) (EU 2016/679) and any applicable national implementing legislation. The Parties shall enter into a Data Processing Agreement (DPA) if personal data is shared or processed by one Party on behalf of the other. Data breaches must be reported to IMY (Integritetsskyddsmyndigheten) within seventy-two (72) hours of discovery.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.liability_indirect",section:"10",label:"Limitation of liability — indirect (§10)",when:function(data){return true;},items:function(data){return "Neither Party shall be liable for any indirect or consequential damages, including loss of profit, loss of revenue, or loss of anticipated savings, regardless of whether such damages were foreseeable.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s10.cap",section:"10",label:"Liability cap (§10)",when:function(data){return true;},items:function(data){return "The aggregate liability of either Party in any twelve (12) month period shall not exceed the total amount paid or payable by the Reseller for the Products during the preceding twelve (12) months.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s10.p1",section:"10",label:"§10 Limitation of Liability / 1",when:function(data){return true;},items:function(data){return "Nothing in this Agreement shall limit either Party\u2019s liability for: (i) death or personal injury caused by negligence; (ii) fraud or fraudulent misrepresentation; or (iii) any other liability that cannot be limited or excluded under applicable law.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.warranty_asis",section:"10",label:"Products “as is” (§10)",when:function(data){return true;},items:function(data){return "The Reseller acknowledges that, except as expressly provided in this Agreement or in the Supplier’s standard warranty terms in Appendix 3, the Products are provided “as is” and the Supplier makes no warranties, express or implied, as to merchantability, fitness for a particular purpose, or non-infringement.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s10.ip",section:"10",label:"IP indemnity (§10)",when:function(data){return true;},items:function(data){return "The Supplier warrants that, to its knowledge, the sale of the Products in the Territory does not infringe any third-party intellectual property rights. If the Reseller receives a third-party IP claim relating to the Products as supplied, the Supplier shall indemnify the Reseller against finally determined liability, damages, and reasonable legal costs, provided the Reseller: (i) gives prompt written notice; (ii) makes no admission of liability without the Supplier\u2019s prior written consent; and (iii) provides reasonable cooperation at the Supplier\u2019s cost. The Supplier\u2019s indemnity does not cover claims arising from the Reseller\u2019s own modifications to the Products or warranties given by the Reseller beyond the Supplier\u2019s standard warranty.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s11.audit",section:"11",label:"Audit (§11)",when:function(data){return true;},items:function(data){return "To ensure compliance with the terms of this Agreement, the Reseller shall, upon receiving at least fourteen (14) days\u2019 prior written notice, grant the Supplier or its appointed representatives reasonable access to relevant sales reports, inventory records, and other documentation as may be reasonably required to verify compliance. Audits shall not be conducted more than once per calendar year, unless there is reasonable documented suspicion of material non-compliance. If an audit reveals material non-compliance, the Reseller shall remedy it within thirty (30) days of written notice. Failure to remedy constitutes a material breach.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s12.p1",section:"12",label:"§12 Notices / 1",when:function(data){return true;},items:function(data){return "Any notice required under this Agreement to be in writing shall be sent to the registered addresses of the Parties or as later updated in writing. Notice shall be deemed received: (i) if delivered by courier, upon delivery; (ii) if sent by registered letter, five (5) business days after posting; and (iii) if sent by email, at the time of transmission, if receipt is confirmed by the recipient Party or if the transmitting Party also sent the notice by registered letter the same day. Written confirmation showing that a notice has been delivered by courier or sent by registered letter shall constitute proof of receipt. Address changes must be communicated within fourteen (14) calendar days.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s13.term",section:"13",label:"Term and termination (§13)",when:function(data){return true;},items:function(data){return "This Agreement shall enter into force when signed by both Parties and shall remain in force until terminated by either Party upon the notice period stated in Appendix 1. If no notice period is specified in Appendix 1, the notice period shall be ninety (90) days.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s13.p1",section:"13",label:"§13 Term and Termination / 1",when:function(data){return true;},items:function(data){return "Upon termination, neither Party shall be entitled to any compensation or indemnity, except for payment of any outstanding and due invoices. Following termination, the Reseller remains obligated to adhere to the terms of this Agreement for any remaining Product inventory until sold or returned.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s13b.no_compensation",section:"13",label:"No compensation on termination (§13B)",when:function(data){return true;},items:function(data){return "The Reseller buys and resells the Products in its own name and for its own account. The Reseller is a reseller and not a commercial agent. The Reseller has no right to severance pay, goodwill compensation, or any other termination indemnity when this Agreement ends, whether by notice, expiry, or termination for cause. This clause applies notwithstanding the Swedish Commercial Agency Act (lag (1991:351) om handelsagentur) and Directive 86/653/EEC.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s13c.after_end",section:"13",label:"After the agreement ends (§13C)",when:function(data){return true;},items:function(data){return "When this Agreement ends, for any reason, the Supplier has no obligation to buy back, repurchase, or otherwise take back the Reseller’s stock or inventory. There is no non-compete after the term of this Agreement.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s14.p1",section:"14",label:"§14 Premature Termination / 1",when:function(data){return true;},items:function(data){return "Either Party shall be entitled to terminate this Agreement with immediate effect where: (i) the other Party has committed a material breach; (ii) the other Party fails to cure a remediable breach within thirty (30) calendar days of written notice; or (iii) the other Party is declared bankrupt, commences company reorganisation, or can otherwise be deemed insolvent.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s14.p2",section:"14",label:"§14 Premature Termination / 2",when:function(data){return true;},items:function(data){return [{t:"Material breach by the Reseller includes, without limitation: ",b:true},"failure to pay in accordance with agreed payment terms; exceeding the Credit Limit without consent; breach of confidentiality; unauthorised sub-reselling; modification of Products without consent; misrepresentation of the Supplier\u2019s warranty to end customers; and persistent non-compliance following written notice."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.s14.p3",section:"14",label:"§14 Premature Termination / 3",when:function(data){return true;},items:function(data){return "Following termination due to material breach, the breaching Party shall immediately cease all activities under this Agreement. In the case of the Reseller\u2019s breach, the Reseller shall, at the Supplier\u2019s discretion, either resell all unsold Products to the Supplier at the Reseller\u2019s expense or continue to sell such Products subject to the terms of this Agreement until all inventory is depleted.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s15.fm",section:"15",label:"Force majeure (§15)",when:function(data){return true;},items:function(data){return "Neither Party shall be deemed in default of this Agreement to the extent that performance of obligations (excluding payment obligations) is delayed or prevented by reason of war, pandemic, strike, fire, natural disaster, civil disturbance, act or ordinance of any governmental authority, terrorism, or any other cause genuinely beyond the reasonable control of such Party and not foreseeable at the time of signing (a \u201cForce Majeure Event\u201d). In the event that either Party\u2019s performance is affected by a Force Majeure Event, such Party shall promptly notify the other Party in writing, providing details of the event and an estimate of the period during which the delay or prevention shall continue. Both Parties agree to use their best efforts to alleviate and mitigate the effects of the Force Majeure Event as promptly as possible. If the Force Majeure Event continues for more than thirty (30) calendar days, either Party may terminate upon written notice without further liability, except for obligations accrued prior to the Force Majeure Event.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s16.p1",section:"16",label:"§16 Miscellaneous / 1",when:function(data){return true;},items:function(data){return [{t:"No partnership. ",b:true},"Nothing in this Agreement constitutes a partnership, joint venture, or relationship of principal and agent between the Parties."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.s16.p2",section:"16",label:"§16 Miscellaneous / 2",when:function(data){return true;},items:function(data){return [{t:"Entire agreement and amendments. ",b:true},"This Agreement supersedes all previous agreements on its subject matter and may only be amended in writing signed by duly authorised representatives of both Parties. Any amendment to, or updated version of, this Agreement, and any notice or other communication under it, shall be sent to the Reseller’s Contract & Notices contact set out in Appendix 1 (Reseller Contact Points) or, if none is designated, to its Main / General contact. The Reseller shall keep that address valid and actively monitored throughout the term, shall notify the Supplier without delay of any change to it, and acknowledges that communications sent to it are deemed duly received. The Supplier may rely on this address for all such communications without awaiting any acknowledgement or signature; where a particular document requires signature, it shall be signed by a person authorised to bind the Reseller."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.s16.p3",section:"16",label:"§16 Miscellaneous / 3",when:function(data){return true;},items:function(data){return [{t:"Assignment. ",b:true},"Neither Party may assign its rights and/or obligations without the prior written consent of the other Party."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.s16.p4",section:"16",label:"§16 Miscellaneous / 4",when:function(data){return true;},items:function(data){return [{t:"Invalidity. ",b:true},"Should any clause in this Agreement or part thereof be void or invalid, the other provisions of the Agreement shall remain in force, and the clause may be amended to the extent such invalidity materially affects the rights or obligations of either Party under this Agreement."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.antibribery",section:"16",label:"Anti-bribery (§16)",when:function(data){return true;},items:function(data){return "Both Parties shall comply with the Swedish Anti-Bribery Act and other applicable anti-bribery and anti-corruption laws.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.s16.p5",section:"16",label:"§16 Miscellaneous / 5",when:function(data){return true;},items:function(data){return [{t:"Survival. ",b:true},"Sections 8 (confidentiality), 10 (limitation of liability), 13 (term and termination), 14 (premature termination), and 17 (governing law and disputes) survive termination or expiry of this Agreement."];},render:function(data){return prose(this.items(data));}},
 {id:"ra.s17.law",section:"17",label:"Governing law (§17)",when:function(data){return true;},items:function(data){return "This Agreement is governed by and construed in accordance with Swedish law. Disputes shall first be resolved through good-faith negotiation. If not resolved within thirty (30) days, the Parties agree to SCC mediation. If mediation fails, the dispute shall be finally settled by SCC arbitration. Seat: Malm\u00f6. Language: English.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.appendix.p1",section:"annex",label:"APPENDIX 1 — RESELLER SPECIFIC TERMS AND CONDITIONS / 1",when:function(data){return true;},items:function(data){return "For matters not handled through the Supplier’s web portal, the Reseller may use the following contact points:";},render:function(data){return prose(this.items(data));}},
 {id:"ra.appendix.p2",section:"annex",label:"APPENDIX 1 — RESELLER SPECIFIC TERMS AND CONDITIONS / 2",when:function(data){return true;},items:function(data){return "The Reseller's contact persons for the following functions:";},render:function(data){return prose(this.items(data));}},
 {id:"ra.appendix.p3",section:"annex",label:"APPENDIX 3 — VENDORA GENERAL TERMS / 3",when:function(data){return true;},items:function(data){return "The Supplier’s full General Terms and Conditions form part of this Agreement and are incorporated by reference. The current version is available at https://www.reseller.vendora.se/en/info/terms-reseller/. The summary below is provided for convenience only; in the event of any conflict between this summary and the full General Terms and Conditions, the full General Terms and Conditions shall prevail.";},render:function(data){return prose(this.items(data));}},
 {id:"ra.appendix.p4",section:"annex",label:"APPENDIX 3 — VENDORA GENERAL TERMS / 4",when:function(data){return true;},items:function(data){return "The version of the General Terms and Conditions in force at the date of signing applies to this Agreement. The Supplier may update the General Terms and Conditions from time to time; any updated version applies to orders placed after the Reseller has been notified of the update, and shall not apply retroactively to orders already confirmed.";},render:function(data){return prose(this.items(data));}}
],
"rb":[
 {id:"rb.s1.p1",section:"1",label:"§1 Parties / 1",when:function(data){return true;},items:function(data){return "This Reseller Agreement is made between:";},render:function(data){return prose(this.items(data));}},
 {id:"rb.s1.p2",section:"1",label:"§1 Appointment / 2",when:function(data){return true;},items:function(data){return "Vendora grants the Reseller a non-exclusive right to actively market and sell "+( data.products||"the Products")+" in "+(data.terr||"the Territory")+". Within the EU/EEA, passive sales cannot be restricted. No sub-resellers without prior written consent.";},render:function(data){return prose(this.items(data));}},
 {id:"rb.s2.payment",section:"2",label:"Orders and payment (§2)",when:function(data){return true;},items:function(data){return "Orders through Vendora’s designated channel. Payment: "+data.pay+" days net in "+data.curr+". Late payment triggers statutory interest. Title remains with Vendora until full payment.";},render:function(data){return prose(this.items(data));}},
 {id:"rb.s3.p1",section:"3",label:"§3 Compliance and Brand / 1",when:function(data){return true;},items:function(data){return "Each Party complies with all applicable laws. The Reseller shall not misrepresent Vendora’s standard warranty. Any additional warranty the Reseller offers end customers is solely the Reseller’s own commitment and cost. The Reseller shall promptly notify Vendora of any suspected counterfeit or grey market products.";},render:function(data){return prose(this.items(data));}},
 {id:"rb.s4.p1",section:"4",label:"§4 Confidentiality / 1",when:function(data){return true;},items:function(data){return "Each Party keeps the other’s Confidential Information confidential. Obligation continues 3 years after termination.";},render:function(data){return prose(this.items(data));}},
 {id:"rb.s5.p1",section:"5",label:"§5 Limitation of Liability / 1",when:function(data){return true;},items:function(data){return "Neither Party liable for indirect or consequential damages. Aggregate liability capped at 12 months’ purchases. Vendora warrants no IP infringement and indemnifies the Reseller for finally determined IP claims relating to the Products as supplied.";},render:function(data){return prose(this.items(data));}},
 {id:"rb.s6.term",section:"6",label:"Term (§6)",when:function(data){return true;},items:function(data){return "Terminable by either party on "+data.notice+" days’ written notice. Immediate termination for uncured material breach or insolvency.";},render:function(data){return prose(this.items(data));}},
 {id:"rb.s7.p1",section:"7",label:"§7 Governing Law / 1",when:function(data){return true;},items:function(data){return "Swedish law. SCC arbitration, seat Malmö, language English.";},render:function(data){return prose(this.items(data));}},
 {id:"rb.appendix.p1",section:"annex",label:"APPENDIX 1 — RESELLER SPECIFIC TERMS / 1",when:function(data){return true;},items:function(data){return "For matters not handled through the Supplier’s web portal, the Reseller may use the following contact points:";},render:function(data){return prose(this.items(data));}},
 {id:"rb.appendix.p2",section:"annex",label:"APPENDIX 1 — RESELLER SPECIFIC TERMS / 2",when:function(data){return true;},items:function(data){return "The Reseller's contact persons for the following functions:";},render:function(data){return prose(this.items(data));}},
 {id:"rb.appendix.p3",section:"annex",label:"APPENDIX 3 — VENDORA GENERAL TERMS / 3",when:function(data){return true;},items:function(data){return "The Supplier’s full General Terms and Conditions form part of this Agreement and are incorporated by reference. The current version is available at https://www.reseller.vendora.se/en/info/terms-reseller/. The summary below is provided for convenience only; in the event of any conflict between this summary and the full General Terms and Conditions, the full General Terms and Conditions shall prevail.";},render:function(data){return prose(this.items(data));}},
 {id:"rb.appendix.p4",section:"annex",label:"APPENDIX 3 — VENDORA GENERAL TERMS / 4",when:function(data){return true;},items:function(data){return "The version of the General Terms and Conditions in force at the date of signing applies to this Agreement. The Supplier may update the General Terms and Conditions from time to time; any updated version applies to orders placed after the Reseller has been notified of the update, and shall not apply retroactively to orders already confirmed.";},render:function(data){return prose(this.items(data));}}
],
"da":[
 {id:"da.s2.p1",section:"2",label:"§2 Purpose and Interpretation / 1",when:function(data){return true;},items:function(data){return "For the purpose of initiating a long-term cooperation between the Parties with the objective to increase sales of the Products in the Territory, the Supplier wishes to appoint the Distributor as the "+data.excl+" distributor of the Supplier\u2019s Products within the Territory, and the Distributor has declared its capability and willingness to accept such appointment.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s2.p2",section:"2",label:"§2 Purpose and Interpretation / 2",when:function(data){return true;},items:function(data){return "This Agreement consists of a main agreement body and three (3) appendices. In the event of any inconsistency, the following order of precedence applies: (1) main agreement body; (2) Appendix 1; (3) Appendix 2; (4) Appendix 3; (5) any order placed under the Agreement.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s3.p1",section:"3",label:"§3 Appointment and Territory / 1",when:function(data){return true;},items:function(data){return "The Supplier hereby appoints the Distributor as the Supplier\u2019s authorised and "+data.excl+" distributor for the distribution of the Products in the Territory as set out in Appendix 1.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s3.p2",section:"3",label:"§3 Appointment and Territory / 2",when:function(data){return true;},items:function(data){return [{t:"Supplier\u2019s non-compete in Territory. ",b:true},"During the term of this Agreement, the Supplier shall not, directly or indirectly, sell or supply the Products to any third party in the Territory \u2014 including distributors, resellers, retailers, agents, or end customers \u2014 without the prior written consent of the Distributor. Any breach entitles the Distributor to claim damages equal to lost margin on diverted sales, and constitutes a material breach entitling the Distributor to terminate with immediate effect."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s3.p3",section:"3",label:"§3 Appointment and Territory / 3",when:function(data){return true;},items:function(data){return [{t:"Sales targets and exclusivity review. ",b:true},"Where annual sales targets are agreed in Appendix 1, the Distributor shall use commercially reasonable efforts to achieve them. Failure to meet a target shall not constitute grounds for termination or removal of exclusivity unless a specific cure mechanism is expressly agreed in Appendix 1. Reduction of exclusive rights requires one hundred and eighty (180) days\u2019 written notice and does not take effect during the first twelve (12) months after signing."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s3.p4",section:"3",label:"§3 Appointment and Territory / 4",when:function(data){return true;},items:function(data){return "The Distributor has the right to describe itself as the Supplier\u2019s \u201cauthorised distributor\u201d of the Products to third parties.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s3.p5",section:"3",label:"§3 Appointment and Territory / 5",when:function(data){return true;},items:function(data){return "The Supplier shall promptly notify the Distributor of any approach or inquiry received from any third party in the Territory relating to the Products, and shall refer all such approaches and inquiries to the Distributor.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s3.p6",section:"3",label:"§3 Appointment and Territory / 6",when:function(data){return true;},items:function(data){return "Outside the Territory and in relation to the Products, the Distributor shall refrain from actively seeking customers, from establishing any branch, and from maintaining any distribution depot. This restriction shall not prevent the Distributor from fulfilling unsolicited (passive) orders received from outside the Territory where permitted by applicable law.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s4.p1",section:"4",label:"§4 Purchase Orders / 1",when:function(data){return true;},items:function(data){return "The Distributor\u2019s purchase orders shall be in writing (including email or EDI) on the Distributor\u2019s standard purchase order form and in accordance with the Trade Routines in Appendix 2. The Supplier shall confirm or reject each order within two (2) business days of receipt; silence constitutes acceptance.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s4.p2",section:"4",label:"§4 Purchase Orders / 2",when:function(data){return true;},items:function(data){return "The Supplier must accept orders in the Distributor\u2019s Order Management System and follow all instructions provided therein. This includes, but is not limited to, confirming orders, providing tracking information, and updating product status in the system. Failure to comply with this requirement may result in delayed processing of orders and payments.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s4.p3",section:"4",label:"§4 Purchase Orders / 3",when:function(data){return true;},items:function(data){return "The Distributor may cancel any purchase order, in full or in part, at any time before dispatch without cost or penalty. The Distributor also has the right to cancel without cost if the ordered Products have not been dispatched within "+data.lead+" calendar days after the confirmed order date.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s5.p1",section:"5",label:"§5 Prices / 1",when:function(data){return true;},items:function(data){return "Unless otherwise expressly agreed in Appendix 1, all Prices are quoted in "+data.pcurr+" on "+data.inco+" "+data.incoy+", "+data.delplace+" terms. Where Appendix 1 specifies DDP Vendora Nordic AB, Lomma, Sweden (Incoterms 2020), the Prices shall be deemed to include delivery to the agreed place of destination, including freight, export clearance, import clearance, customs duties, and all other costs for which the Supplier is responsible under the agreed Incoterm. The Supplier may not invoice any additional shipping, logistics, delivery, customs, or import-related charges unless expressly agreed in writing by the Distributor in advance. Any applicable value added tax or sales tax shall be added separately where required by law.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s5.p2",section:"5",label:"§5 Prices / 2",when:function(data){return true;},items:function(data){return "If another Incoterm is expressly agreed in writing between the Parties for a particular shipment or Product line, the allocation of costs and risks shall follow that agreed Incoterm (Incoterms 2020), and the Prices shall be adjusted accordingly.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s5.p3",section:"5",label:"§5 Prices / 3",when:function(data){return true;},items:function(data){return "The Supplier shall maintain up-to-date Product Prices and shall notify the Distributor of any price change in accordance with this section. The Prices do not include Market Development Funds (MDF) support, Return Merchandise Authorization (RMA) support, or any other backend rebate as stated in Appendix 1.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s5.payment",section:"5",label:"Payment (§5)",when:function(data){return true;},items:function(data){return "The Distributor shall pay for all ordered Products by bank transfer in "+data.curr+", within "+data.pay+" days from the invoice date, or such other payment term as set out in Appendix 1. Invoices shall be sent electronically to "+data.invmail+" only after dispatch.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s5.p4",section:"5",label:"§5 Price Protection / 4",when:function(data){return true;},items:function(data){return "If the Supplier reduces its transfer price or the MSRP for any Product by more than five (5) per cent (other than by promotional or temporary discounts), the Supplier shall issue a credit equal to the price difference for all units of that Product remaining in the Distributor\u2019s inventory as of the effective date of the reduction. For the purposes of this clause, \u201cinventory\u201d includes all units purchased within the preceding one hundred and eighty (180) calendar days that have not yet been invoiced to a customer. The Supplier shall provide no less than thirty (30) days\u2019 written advance notice before any permanent price reduction takes effect. If the Supplier implements a price reduction without providing the required notice, the Distributor shall be entitled to apply the credit retroactively.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s5.p5",section:"5",label:"§5 Price Increases / 5",when:function(data){return true;},items:function(data){return "Price increases require written agreement by both Parties at least ninety (90) days in advance of the effective date. Increases do not apply to orders confirmed prior to the notice date. If the Supplier implements an increase without the required notice, the Distributor may: (i) cancel affected open orders without penalty; (ii) treat the increase as void and continue purchasing at the previous prices; or (iii) accept the new prices with effect from the date the ninety-day notice would have expired.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s6.warranty",section:"6",label:"Warranty (§6)",when:function(data){return true;},items:function(data){return "The Supplier warrants that the Products delivered under this Agreement are free from defects in materials and workmanship and conform to their specifications for a period of twenty-four (24) months from the date of delivery to the Distributor.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s6.p1",section:"6",label:"§6 Certifications and Compliance Documentation / 1",when:function(data){return true;},items:function(data){return "The Supplier shall provide all required certifications, compliance documentation, CE markings, RoHS, REACH declarations, and all documentation necessary for the lawful sale and distribution of the Products in each country within the Territory, kept up-to-date throughout the term.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s6.p2",section:"6",label:"§6 Product Data (PIM) / 2",when:function(data){return true;},items:function(data){return "The Supplier shall provide complete, accurate and up-to-date product data for all Products in the Distributor\u2019s designated PIM format. The Supplier shall complete all mandatory fields within ten (10) business days of receipt of the template, and in any event before the first shipment, launch, or sale of the relevant Product in the Territory. The minimum product data shall include, where applicable: SKU/MPN, product name and family, EAN/UPC, HS code, EU CN code and TARIC classification where applicable, non-preferential country of origin, preferential origin status where applicable, regulatory and dangerous goods information, unit/inner box/master carton/pallet dimensions and weights, battery type, capacity in Wh, lithium content where relevant, dangerous goods or battery classification, WEEE/EPR and battery registration references, declarations of conformity, certifications, and EOL status; launch date, lead time, short and long descriptions, category mappings, recommended retail prices, Distributor buying price, warranty terms, packaging material data, packaging language, box contents, power specifications, manual links, compatibility data, product images, copy text, SEO and meta data, and key features.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s6.p3",section:"6",label:"§6 EU Customs Classification and Origin / 3",when:function(data){return true;},items:function(data){return "The Supplier shall provide, warrant, and maintain the correct customs classification for each Product for importation into the European Union, including the applicable HS code, CN code and TARIC classification where relevant, together with the correct non-preferential country of origin and, where applicable, preferential origin status and supporting origin documentation. The Supplier shall be liable for all documented direct costs, additional duties, reclassification costs, customs broker fees, storage costs, delay costs, and penalties arising from incorrect, incomplete, or outdated customs classification or origin data.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s6.p4",section:"6",label:"§6 EU Customs Classification and Origin / 4",when:function(data){return true;},items:function(data){return "The Supplier shall ensure that the Products comply with all applicable European Union rules and regulations, notably CE marking, the Radio Equipment Directive (RED) where applicable, RoHS, and REACH, and shall provide the corresponding declarations of conformity and supporting documentation.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s6.p5",section:"6",label:"§6 EU Customs Classification and Origin / 5",when:function(data){return true;},items:function(data){return "The Supplier shall update all product data without undue delay and no later than ten (10) business days after any change. The same customs and trade data (HS code, CN code, TARIC classification, and country of origin) shall be used consistently in the PIM, commercial invoices, packing lists, customs documentation, and other shipping and trade documents. The Supplier shall notify the Distributor in writing of any change to a Product\u2019s customs classification or country of origin before the affected shipment is dispatched.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s6.p6",section:"6",label:"§6 Consequences of Non-Compliance with Product Data Obligations / 6",when:function(data){return true;},items:function(data){return "Where the Supplier fails to provide complete, accurate, and up-to-date product data, customs data, certifications, or compliance documentation as required under this section, the Distributor shall be entitled to suspend onboarding, listing, launch, or order processing of the affected Products until the deficiency has been remedied, without such suspension constituting a breach by the Distributor or relieving the Supplier of any obligation under this Agreement. The Supplier shall additionally be liable for any documented, direct loss, cost, or rework caused by materially incomplete, inaccurate, or outdated Product data, subject to the limitation of liability in section 13.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s7.p1",section:"7",label:"§7 Compliance with Laws / 1",when:function(data){return true;},items:function(data){return "Each Party shall comply with all applicable laws, regulations, business ethics, and industry standards, including: anti-bribery and anti-corruption laws; competition and antitrust laws; sustainability and environmental laws; labour and human rights laws; and customs, export control, trade compliance, tariff classification, and origin-marking laws.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s7.p2",section:"7",label:"§7 Compliance with Laws / 2",when:function(data){return true;},items:function(data){return "The Supplier shall comply with all applicable customs and trade requirements relevant to the Products, including correct tariff classification, origin declarations, export documentation, and all product-related customs information required for lawful importation into the Territory.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s7.p3",section:"7",label:"§7 Compliance with Laws / 3",when:function(data){return true;},items:function(data){return "Upon written request from the Distributor, the Supplier shall complete, sign, and return all supplier compliance, sustainability, due diligence, code of conduct, and related documentation within thirty (30) days of the request. Failure to provide the requested documentation shall constitute a material breach if not remedied within thirty (30) days after written notice.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s7.p4",section:"7",label:"§7 Compliance with Laws / 4",when:function(data){return true;},items:function(data){return "Each Party represents and warrants that it shall comply with all applicable laws, regulations, business ethics and industry standards in connection with its activities under this Agreement. Upon request from the Distributor, the Supplier shall provide information regarding the measures implemented to ensure such compliance. Repeated or serious violations of this clause shall constitute a material breach, entitling the Distributor to terminate this Agreement with immediate effect.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s7.p5",section:"7",label:"§7 Compliance with Laws / 5",when:function(data){return true;},items:function(data){return "Both Parties shall maintain policies prohibiting bribery, corruption, and other unethical business practices, and shall conduct their business in accordance with the highest standards of ethical conduct.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s7.p6",section:"7",label:"§7 Compliance with Laws / 6",when:function(data){return true;},items:function(data){return "The Distributor may introduce sustainability guidelines, a supplier code of conduct, and product stewardship programs during the term of this Agreement, on ninety (90) days\u2019 written notice, which the Supplier shall make reasonable efforts to implement.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s8.p1",section:"8",label:"§8 Delivery and Inspection of Goods / 1",when:function(data){return true;},items:function(data){return "The Supplier shall dispatch ordered Products within "+data.lead+" calendar days of a confirmed purchase order, under "+data.inco+" ("+data.incoy+"), "+data.delplace+", unless otherwise agreed in writing.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s8.p2",section:"8",label:"§8 Delivery and Inspection of Goods / 2",when:function(data){return true;},items:function(data){return "The Supplier shall ensure that each shipment is accompanied by commercial invoices, packing lists, customs documents, and origin documents that correctly reflect the applicable Product description, HS code, EU CN code and TARIC classification where relevant, non-preferential country of origin, and any dangerous goods or battery classification. The customs and trade data used in shipment documents must match the latest data submitted in Vendora\u2019s designated PIM template.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s8.p3",section:"8",label:"§8 Delivery and Inspection of Goods / 3",when:function(data){return true;},items:function(data){return "The Distributor shall inspect all Products upon delivery and notify the Supplier in writing of any visible damages, defects, or shortages within thirty (30) calendar days of receipt. Hidden defects must be reported as soon as reasonably possible after discovery, and no later than the end of the Warranty Period.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s8.p4",section:"8",label:"§8 Delivery and Inspection of Goods / 4",when:function(data){return true;},items:function(data){return "The Supplier is responsible for obtaining any necessary export licences, certificates of origin, or other governmental approval required to sell the Products within the European Union.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s8.p5",section:"8",label:"§8 Delivery and Inspection of Goods / 5",when:function(data){return true;},items:function(data){return "The Supplier shall confirm the dispatch time with tracking information in the Distributor\u2019s Order Management System. Upon request from the Distributor, the relevant customs authority, or a customs broker, the Supplier shall provide clarifications, revised documents, or supporting evidence in relation to a shipment.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s8.p6",section:"8",label:"§8 Delivery and Inspection of Goods / 6",when:function(data){return true;},items:function(data){return "If the Supplier accepts the Distributor\u2019s complaint as valid, the Supplier shall issue a credit note for the non-conforming Products, or arrange replacement, within thirty (30) calendar days of accepting the complaint. The credit note may be deducted from invoices due or applied against future purchases.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p1",section:"9",label:"§9 Stock Rotation Rights / 1",when:function(data){return true;},items:function(data){return "The Distributor shall have the right to return slow-moving or excess inventory to the Supplier "+data.rotw+" per calendar year, with a total annual value not exceeding "+(data.rot||"[___]")+"% of the previous year\u2019s net purchases.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p2",section:"9",label:"§9 Stock Repurchase upon Termination / 2",when:function(data){return true;},items:function(data){return "Upon termination or expiry of this Agreement for any reason, the Distributor shall have the right to return all unsold Active Products to the Supplier for full credit at the Repurchase Price.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p3",section:"9",label:"§9 Stock Repurchase upon Termination / 3",when:function(data){return true;},items:function(data){return [{t:"Mandatory repurchase obligation. ",b:true},"If this Agreement is terminated, not renewed, or expires following notice from either Party, for any reason other than the Distributor\u2019s material breach, the Supplier shall repurchase all Active Products remaining in the Distributor\u2019s inventory at the Repurchase Price, being the book value of the relevant Products (purchase price paid to the Supplier plus documented inbound logistics costs: freight, customs duties, and import charges). The Supplier shall settle the repurchase amount by payment or credit note, at the Distributor\u2019s election, within thirty (30) calendar days."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p4",section:"9",label:"§9 Stock Repurchase upon Termination / 4",when:function(data){return true;},items:function(data){return [{t:"Active Products \u2014 meaning. ",b:true},"\u201cActive Products\u201d means all Products that have at any time been supplied to, approved for sale by, or otherwise made available to the Distributor under this Agreement, and that remain in the Distributor\u2019s inventory, irrespective of their current sales velocity or assortment status."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p5",section:"9",label:"§9 Stock Repurchase upon Termination / 5",when:function(data){return true;},items:function(data){return [{t:"Valid EOL notice. ",b:true},"A valid end-of-life (EOL) notice must be in writing, must identify the relevant Product and SKU/MPN, must state the effective EOL date, and must be given to the Distributor at least one hundred and eighty (180) days before that effective date."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p6",section:"9",label:"§9 Stock Repurchase upon Termination / 6",when:function(data){return true;},items:function(data){return [{t:"Active Products definition. ",b:true},"No Product shall cease to be an Active Product solely by reason of reduced or absent sales, reduced or absent deliveries, internal assortment classifications, replacement, phase-out status, or removal from the Supplier\u2019s price lists, catalogues, websites, or marketing materials, unless valid prior written EOL notice has been provided at least one hundred and eighty (180) days in advance. In the absence of such valid prior written notice, the Supplier may not invoke any alleged discontinuation or phase-out as grounds for refusing repurchase, return, credit, support, supply, or any other obligation under this Agreement. The Supplier bears the burden of proving that valid prior written notice was received by the Distributor."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p7",section:"9",label:"§9 Return Process / 7",when:function(data){return true;},items:function(data){return "The Distributor shall submit a list of Products proposed for return to the Supplier at least thirty (30) days before the intended return date. The Supplier shall review and approve returns within ten (10) business days of receipt of the Distributor\u2019s request, with approval not to be unreasonably withheld. Only current, unopened, and saleable Products in original packaging shall be eligible for return. Products specifically ordered by the Distributor for a particular customer that are not part of the standard product offering shall not be eligible for return unless defective. The Distributor shall be responsible for the cost of shipping Products back to the Supplier unless otherwise agreed.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p8",section:"9",label:"§9 Credit Terms / 8",when:function(data){return true;},items:function(data){return "The Supplier shall settle approved returns by payment or credit note, at the Distributor\u2019s election, at the original purchase price within thirty (30) calendar days of receiving the returned Products. Credit notes may be applied against due or future invoices.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s9.p9",section:"9",label:"§9 Credit Terms / 9",when:function(data){return true;},items:function(data){return [{t:"Repurchase Price. ",b:true},"The \u201cRepurchase Price\u201d means the book value of the relevant Products (the purchase price paid to the Supplier plus documented inbound logistics costs: freight, customs duties, and import charges). In no event shall the Repurchase Price be lower than the original invoice price paid by the Distributor for the relevant Products."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s10.p1",section:"10",label:"§10 Service and Support / 1",when:function(data){return true;},items:function(data){return "The Supplier shall: provide a dedicated point of contact for product enquiries, technical support, and account management; respond to technical support queries within twenty-four (24) hours on business days; provide access to up-to-date marketing materials; issue credits for defective Products in accordance with the RMA process; and provide regular product and troubleshooting training to the Distributor\u2019s staff.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s10.p2",section:"10",label:"§10 Service and Support / 2",when:function(data){return true;},items:function(data){return [{t:"Distributor obligations. ",b:true},"The Distributor shall: ensure that its staff is well-trained on the Supplier\u2019s product portfolio; provide competent and trained staff and appropriate service facilities to offer prompt and professional service; provide email and phone support to its customers on all Products; and provide the Supplier with a quarterly report of warranty returns."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s10.p3",section:"10",label:"§10 RMA (Return Merchandise Authorization) Handling / 3",when:function(data){return true;},items:function(data){return "The Parties shall establish and maintain a joint RMA tracking system to ensure efficient processing of all returns.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s10.p4",section:"10",label:"§10 RMA (Return Merchandise Authorization) Handling / 4",when:function(data){return true;},items:function(data){return [{t:"The Distributor shall: ",b:true},"provide first-level support for end customers and resellers; issue RMA numbers for approved returns; where required, handle the physical receipt and inspection of returned Products; provide the Supplier with detailed information about defective Products; and maintain accurate records of all RMA transactions."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s10.p5",section:"10",label:"§10 RMA (Return Merchandise Authorization) Handling / 5",when:function(data){return true;},items:function(data){return [{t:"The Supplier shall: ",b:true},"provide technical support to the Distributor for complex issues; issue credit notes within thirty (30) days of receiving RMA information; cover all shipping costs associated with the return of defective Products from the Distributor; and provide regular training to the Distributor\u2019s staff regarding troubleshooting of Products. The maximum defective rate (MDR) and related thresholds are set out in Appendix 1."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s11.p1",section:"11",label:"§11 Intellectual Property Rights / 1",when:function(data){return true;},items:function(data){return "All intellectual property rights, including but not limited to trademarks, trade names, logos, patents, copyrights, trade secrets, and other proprietary information relating to the Products, are and shall remain the sole property of the Supplier.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s11.p2",section:"11",label:"§11 Intellectual Property Rights / 2",when:function(data){return true;},items:function(data){return "The Distributor shall not make any modifications to the Products or their packaging.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s11.p3",section:"11",label:"§11 Intellectual Property Rights / 3",when:function(data){return true;},items:function(data){return "The Supplier grants a non-exclusive, non-transferable licence to the Distributor to use the Supplier\u2019s trademarks, trade names, and logos in connection with the marketing, promotion, and sale of the Products in the Territory. The Distributor may create, publish, and maintain brand pages, product listings, and marketing content across digital and physical channels, and may translate, localise, and adapt content for local market conditions, SEO, and AIEO purposes. The Distributor’s own brand pages, product pages, product listings, and search-optimised marketing content do not require prior approval, it being acknowledged that such pages are a primary channel through which the Distributor markets the Products and generates organic and paid traffic in the Territory. The Distributor shall follow the Supplier’s brand guidelines where these have been provided in writing, and shall correct or remove any specific item of content upon the Supplier’s reasonable written request.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s11.p4",section:"11",label:"§11 Intellectual Property Rights / 4",when:function(data){return true;},items:function(data){return "The Distributor may operate and maintain dedicated brand and product pages referencing the Supplier\u2019s brand for the purpose of promoting the Products and informing customers in the Territory, and may direct customers to authorised resellers of the Products in the Territory. This right subsists for as long as the Distributor is appointed as a distributor of the Products under this Agreement and applies to the Distributor\u2019s own websites and channels, including the use of the brand name in page titles, descriptions, and URLs to the extent reasonably necessary for those purposes.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s11.p5",section:"11",label:"§11 Intellectual Property Rights / 5",when:function(data){return true;},items:function(data){return [{t:"IP defence (Alt A \u2014 full protection). ",b:true},"If legal measures are taken or threatened against the Distributor claiming that the Products infringe any third-party intellectual property rights in the Territory, the Distributor shall promptly notify the Supplier in writing. The Supplier shall, upon such notification and at its own cost, take over the conduct of the defence of such claim (including the instruction of legal counsel) and shall keep the Distributor regularly informed. The Distributor shall provide the Supplier with all reasonable assistance requested, at the Supplier\u2019s cost. The Supplier shall bear all costs and expenses from the date of notification onwards."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s11.p6",section:"11",label:"§11 Intellectual Property Rights / 6",when:function(data){return true;},items:function(data){return "The Supplier shall not enter into any settlement of any such claim that: (i) imposes any financial liability on the Distributor; (ii) restricts the Distributor\u2019s ability to continue marketing or selling the Products in the Territory; or (iii) otherwise adversely affects the Distributor\u2019s rights or business, without the prior written consent of the Distributor.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s11.p7",section:"11",label:"§11 Intellectual Property Rights / 7",when:function(data){return true;},items:function(data){return "The Supplier shall indemnify and hold harmless the Distributor against all liability, damages, costs, and expenses (including all legal costs on a full indemnity basis) that are finally determined, or that the Distributor is required to pay pursuant to a settlement approved in advance by the Supplier. The Supplier\u2019s indemnification obligations under this section shall not be subject to the aggregate liability cap in section 13.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s11.p8",section:"11",label:"§11 Intellectual Property Rights / 8",when:function(data){return true;},items:function(data){return "Post-termination: The Distributor may retain and continue to publish historical, editorial, comparative, informational, review-based, or SEO/AIEO-oriented content, including historical brand pages and product content, after termination, provided discontinued Products are not presented as currently orderable.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s12.p1",section:"12",label:"§12 Confidentiality / 1",when:function(data){return true;},items:function(data){return "During the term of this Agreement, and for a period of three (3) years thereafter, the receiving Party undertakes not to disclose, without the disclosing Party\u2019s prior written consent, any Confidential Information regarding the disclosing Party\u2019s business, nor to use such information for any purpose other than the performance of its obligations under this Agreement.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s12.p2",section:"12",label:"§12 Confidentiality / 2",when:function(data){return true;},items:function(data){return "This confidentiality undertaking shall not apply to information that the receiving Party can prove it learned of in a manner other than through this Agreement, or which is or becomes public knowledge other than through a breach of this Agreement. Nor does this undertaking apply where the receiving Party is required to disclose information in accordance with any law, enactment, stock market regulation, or decision by a governmental authority or court, provided that the receiving Party gives the disclosing Party prompt notice and cooperates in seeking protection of the information.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s13.p1",section:"13",label:"§13 Limitation of Liability / 1",when:function(data){return true;},items:function(data){return "Neither Party shall be liable for any indirect, consequential, special, incidental, or punitive damages, including loss of profit, loss of revenue, or loss of anticipated savings, regardless of whether such damages were foreseeable.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s13.p2",section:"13",label:"§13 Limitation of Liability / 2",when:function(data){return true;},items:function(data){return "Subject to the exceptions below, the aggregate liability of either Party in any twelve (12) month period shall not exceed the total net purchase value invoiced by the Supplier to the Distributor during the preceding twelve (12) months.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s13.p3",section:"13",label:"§13 Limitation of Liability / 3",when:function(data){return true;},items:function(data){return "The above limitations shall not apply to: (i) liability for death or personal injury caused by negligence; (ii) liability for fraud or fraudulent misrepresentation; (iii) the Supplier\u2019s IP indemnification obligations under section 11; (iv) the Supplier\u2019s repurchase obligations under section 9; (v) the Supplier\u2019s liability for documented direct costs arising from materially incorrect, incomplete, or outdated customs classification, origin, or mandatory product data; or (vi) any other liability that cannot be limited or excluded under applicable law.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s14.p1",section:"14",label:"§14 GDPR and Data Protection / 1",when:function(data){return true;},items:function(data){return "Both Parties agree to comply with the General Data Protection Regulation (GDPR) (EU 2016/679) and any applicable national implementing legislation. Data breaches affecting personal data shared under this Agreement must be reported to the other Party and to IMY (Integritetsskyddsmyndigheten) within seventy-two (72) hours of discovery, in accordance with Article 33 GDPR.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s14.p2",section:"14",label:"§14 GDPR and Data Protection / 2",when:function(data){return true;},items:function(data){return "Each Party shall implement appropriate technical and organizational measures to ensure and to be able to demonstrate that processing is performed in accordance with the GDPR. The Parties shall enter into a Data Processing Agreement (DPA) if and to the extent personal data is shared between them or processed by one Party on behalf of the other.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s15.p1",section:"15",label:"§15 Notices / 1",when:function(data){return true;},items:function(data){return "Any notice required under this Agreement to be in writing shall be sent to the addresses in Appendix 3 or as later updated. Notice shall be deemed received: (i) if by courier: upon delivery; (ii) if by registered letter: five (5) business days after posting; (iii) if by email: at the time of transmission, if receipt is confirmed by the recipient Party or if the transmitting Party also sent the notice by registered letter the same day. Written confirmation showing that a notice has been delivered by courier or sent by registered letter shall constitute proof of receipt. Any change of address must be communicated within fourteen (14) calendar days.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s16.p1",section:"16",label:"§16 Term / 1",when:function(data){return true;},items:function(data){return "This Agreement shall enter into force when signed by both Parties and shall remain in force for an initial period of "+data.term+" years, unless a written notice of termination has been given by either Party no less than six (6) months prior to the end of the initial term. If no such notice is given, the Agreement shall automatically extend for successive periods of one (1) year, subject to the same six (6) months\u2019 notice requirement.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s16.p2",section:"16",label:"§16 Term / 2",when:function(data){return true;},items:function(data){return "Any notice of termination or non-renewal issued by the Supplier shall be subject to the Supplier\u2019s stock repurchase obligations under section 9.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s17.p1",section:"17",label:"§17 Premature Termination / 1",when:function(data){return true;},items:function(data){return "Either Party shall be entitled to terminate this Agreement with immediate effect where: (i) the other Party has committed a material breach; (ii) the other Party fails to cure a remediable breach within thirty (30) calendar days of written notice; or (iii) the other Party is declared bankrupt, commences company reorganisation, commences composition with its creditors, or can otherwise be deemed insolvent.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s17.p2",section:"17",label:"§17 Premature Termination / 2",when:function(data){return true;},items:function(data){return "Notice of termination must always be given in writing, without unreasonable delay after the terminating Party learns of the circumstance which is invoked as grounds for termination.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s18.p1",section:"18",label:"§18 Force Majeure / 1",when:function(data){return true;},items:function(data){return "Neither Party shall be in default of this Agreement to the extent that performance is delayed or prevented by reason of war, pandemic, strike, fire, natural disaster, civil disturbance, act or ordinance of any governmental authority, terrorism, or any other cause genuinely beyond the reasonable control of such Party and not foreseeable at the time of signing (a \u201cForce Majeure Event\u201d). In the event that either Party\u2019s performance is affected by a Force Majeure Event, such Party shall promptly notify the other Party in writing, providing details of the event and an estimate of the period during which the delay or prevention shall continue. Both Parties agree to use their best efforts to alleviate and mitigate the effects of the Force Majeure Event as promptly as possible. If the Force Majeure Event continues for more than thirty (30) calendar days, either Party may terminate upon written notice without liability, except for obligations accrued prior to the Force Majeure Event. The Supplier\u2019s stock repurchase obligations under section 9 shall survive any such termination.";},render:function(data){return prose(this.items(data));}},
 {id:"da.s19.p1",section:"19",label:"§19 Miscellaneous / 1",when:function(data){return true;},items:function(data){return [{t:"No partnership. ",b:true},"Nothing in this Agreement constitutes a partnership, joint venture, or relationship of principal and agent between the Parties."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s19.p2",section:"19",label:"§19 Miscellaneous / 2",when:function(data){return true;},items:function(data){return [{t:"Entire agreement and amendments. ",b:true},"This Agreement supersedes all previous agreements and may not be modified except by a written instrument signed by duly authorised representatives of both Parties."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s19.p3",section:"19",label:"§19 Miscellaneous / 3",when:function(data){return true;},items:function(data){return [{t:"Invalidity. ",b:true},"Should any clause in this Agreement or part thereof be void or invalid, the other provisions of the Agreement shall remain in force, and the clause may be amended to the extent such invalidity materially affects the rights or obligations of either Party under this Agreement."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s19.p4",section:"19",label:"§19 Miscellaneous / 4",when:function(data){return true;},items:function(data){return [{t:"Counterparts. ",b:true},"This Agreement may be executed in any number of counterparts, each of which when executed and delivered shall constitute an original, and all of which together shall constitute one and the same instrument. Electronic signatures shall be deemed valid and binding."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s19.p5",section:"19",label:"§19 Miscellaneous / 5",when:function(data){return true;},items:function(data){return [{t:"Assignment. ",b:true},"Neither Party may assign its rights and/or obligations without the prior written consent of the other Party. Either Party may, without consent, assign this Agreement to a successor entity in connection with a merger, acquisition, or sale of substantially all of its assets, provided the assignee assumes all obligations."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s19.p6",section:"19",label:"§19 Miscellaneous / 6",when:function(data){return true;},items:function(data){return [{t:"Survival. ",b:true},"The following sections shall survive termination or expiry: sections 9 (stock repurchase), 11 (IP warranties and post-termination content), 12 (confidentiality), 13 (limitation of liability), and 20 (governing law)."];},render:function(data){return prose(this.items(data));}},
 {id:"da.s20.p1",section:"20",label:"§20 Governing Law / 1",when:function(data){return true;},items:function(data){return "This Agreement is governed by and construed in accordance with Swedish law, without regard to its conflict of law provisions. Disputes shall first be resolved through good-faith negotiations. If not resolved within thirty (30) days of a written request, the Parties agree to submit to SCC mediation, unless one Party objects. If mediation fails, the dispute shall be finally settled by SCC arbitration. Rules for Expedited Arbitrations apply unless the SCC determines otherwise. Seat: Malm\u00f6. Language: English.";},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p1",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 1",when:function(data){return true;},items:function(data){return "Within two (2) banking days after receiving a PO, the order must be confirmed in Vendora\u2019s Order Management System (PO portal).";},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p2",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 2",when:function(data){return true;},items:function(data){return "It is crucial that information is given on the estimated time of arrival (ETA) of the Products and that tracking information is submitted to ensure warehouse slots. If Products on the PO are not in stock, Vendora requires the Supplier to provide Vendora with an ETA for those Products.";},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p3",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 3",when:function(data){return true;},items:function(data){return [{t:"Onboarding gate. ",b:true},"A PIM link shall be provided to the Supplier upon signing. All mandatory product data, digital assets, and compliance documentation must be submitted and complete in the PIM before onboarding, listing, or first shipment of the relevant Products. The Supplier shall update product data within ten (10) business days of any change to specifications, pricing, EAN/UPC, warranty terms, HS/CN/TARIC classification, country of origin, logistics data, battery data, or EOL status."];},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p4",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 4",when:function(data){return true;},items:function(data){return "The Supplier shall maintain a single source of truth for all Product, customs, and logistics data in Vendora\u2019s designated PIM. The HS code, EU CN code, TARIC classification, and non-preferential country of origin submitted in the PIM shall be used consistently across commercial invoices, packing lists, customs declarations, and all shipping and trade documents. Any change to specifications, pricing, EAN/UPC, warranty terms, customs classification, origin, logistics data, battery data, or EOL status must be reflected in the PIM within ten (10) business days of the change, and the Supplier shall notify the Distributor in writing of any customs classification or origin change before the next affected shipment is dispatched.";},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p5",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 5",when:function(data){return true;},items:function(data){return "Where customs, origin, or product data submitted by the Supplier is incorrect, incomplete, or outdated, the Distributor may suspend onboarding, listing, launch, or order processing of the affected Products until corrected, and the Supplier shall bear all resulting documented direct costs, additional duties, reclassification costs, customs broker fees, storage costs, delay costs, and penalties.";},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p6",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 6",when:function(data){return true;},items:function(data){return [{t:"Agreed delivery term: ",b:true}, data.inco+" "+data.delplace+" ("+data.incoy+"). Vendora\u2019s standard for all deliveries is DDP or DAP to Vendora Nordic AB, Ladug\u00e5rdsv\u00e4gen 1, 234 35 Lomma: the Supplier arranges and pays for transport to the place of delivery with a carrier of its own choice, and bears the risk until the Products have been delivered there."];},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p7",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 7",when:function(data){return true;},items:function(data){return [{t:"Shipments on any other term (e.g. EXW, FCA, FOB, CIF). ",b:true},"Where a shipment is not delivered DDP or DAP, the Supplier shall check with Vendora\u2019s logistics department (logistics@vendora.se) before any freight is booked, so that the best price can be secured. The Supplier sends the shipment details \u2014 PO number, number of packages or pallets, dimensions and weight per unit, pick-up address and the date the goods are ready \u2014 together with its own proposed carrier and freight cost, if it has one. Vendora compares this with its own freight agreements and responds within three (3) business days, confirming either the Supplier\u2019s proposal or Vendora\u2019s own booking, with booking instructions or a shipping label where applicable. Nothing may be dispatched until Vendora has confirmed. If the Supplier ships without Vendora\u2019s confirmation, Vendora may invoice the Supplier for the difference between the actual freight cost and the routing Vendora would have confirmed, and for any additional costs that arise."];},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p8",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 8",when:function(data){return true;},items:function(data){return "For every shipment, regardless of delivery term, the tracking number and the commercial invoice shall be uploaded in the PO portal as soon as the goods have been collected.";},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p9",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 9",when:function(data){return true;},items:function(data){return "All Products must be packed and sealed in a secure way to avoid damage, loss, and theft. The Supplier must ensure that all necessary documentation is included in each shipment. Extra costs associated with delays, faulty products, or errors in shipment will be invoiced to the Supplier; the Supplier shall not be accountable for delays caused by the shipping agent.";},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p10",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 10",when:function(data){return true;},items:function(data){return "Each shipment must include correct HS code, EU CN code, TARIC classification, non-preferential country of origin, and supporting customs documents. These must match the latest PIM data submitted to Vendora. Any discrepancy constitutes non-compliance.";},render:function(data){return prose(this.items(data));}},
 {id:"da.appendix.p11",section:"annex",label:"APPENDIX 2 — VENDORA NORDIC AB TRADE ROUTINES / 11",when:function(data){return true;},items:function(data){return "Non-compliant shipments: (i) returned at Supplier’s cost; or (ii) 2% of invoice value (min. EUR 200) + handling costs. Costs from incorrect customs classification, origin data, or shipment documents borne by the Supplier.";},render:function(data){return prose(this.items(data));}}
],
};
return {catalog:function(type){return all[type]||[];},items:function(type,id,data){var row=(all[type]||[]).find(function(x){return x.id===id;});return row?row.items(data||{}):'';},text:function(type,id,data){var row=(all[type]||[]).find(function(x){return x.id===id;});return row?row.render(data||{}):null;}};
});
